import { drawStamp } from "./stamps";

// ── Freehand stroke drawing + per-page item dispatch ──────────────────────
// `redrawAll` renders a page's full annotation array — freehand strokes AND
// stamps share the same array (discriminated by `item.type`), so undo/redo
// (which snapshot/restore that whole array) needed no changes to support
// stamps — see stamps.js for the stamp shape and rendering.

export function drawStroke(ctx, stroke) {
  if (!stroke.points || stroke.points.length < 2) return;
  ctx.save();
  ctx.globalCompositeOperation = stroke.tool === "eraser" ? "destination-out" : "source-over";
  ctx.strokeStyle = stroke.color;
  ctx.lineWidth   = stroke.width;
  ctx.lineCap     = "round";
  ctx.lineJoin    = "round";
  ctx.globalAlpha = stroke.tool === "highlight" ? 0.45 : 1;
  ctx.beginPath();
  ctx.moveTo(stroke.points[0].x, stroke.points[0].y);
  for (let i = 1; i < stroke.points.length; i++) {
    const mid = {
      x: (stroke.points[i - 1].x + stroke.points[i].x) / 2,
      y: (stroke.points[i - 1].y + stroke.points[i].y) / 2,
    };
    ctx.quadraticCurveTo(stroke.points[i - 1].x, stroke.points[i - 1].y, mid.x, mid.y);
  }
  ctx.stroke();
  ctx.restore();
}

export function drawItem(ctx, item, selectedId) {
  if (item.type === "stamp") { drawStamp(ctx, item, item.id === selectedId); return; }
  drawStroke(ctx, item); // default — freehand stroke (legacy items have no `type` at all)
}

export function redrawAll(canvas, items, selectedId) {
  const ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  items.forEach(it => drawItem(ctx, it, selectedId));
}

export const ptDist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
